/**
 * Pushes the fixture payloads generated by generate-datasets.ts into the
 * STATUS_CACHE KV namespace under `dataset:{name}` keys -- the single KV
 * payload source both the (future) Datasets API and notify-commuters cron
 * read (design.md line 608: "Datasets API と通知 Cron が同一の KV payload
 * を読む"). Design.md declares only one new KV binding, STATUS_CACHE
 * (line 514/115); it is dual-purposed for ODPT status caching *and*
 * dataset storage, differentiated by key prefix, not by a second binding.
 *
 * Defaults to local Miniflare storage (`--local`, safe, no live resource).
 * `--remote` writes to the real Cloudflare account and additionally
 * requires the STATUS_CACHE namespace to have actually been created via
 * `wrangler kv namespace create` first (the id in wrangler.jsonc is a
 * placeholder) -- treat `--remote` as a deliberate, human-invoked action.
 *
 * Run: pnpm --filter backend run push:datasets [-- --remote]
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const DATASET_NAMES = ["timetable", "congestion", "correction"] as const;

function main() {
  const remote = process.argv.includes("--remote");
  const fixturesDir = join(import.meta.dirname, "..", "fixtures", "datasets");

  const bulkEntries = DATASET_NAMES.map((name) => {
    const filePath = join(fixturesDir, `${name}.json`);
    const contents = readFileSync(filePath, "utf8");
    // Re-stringify without pretty-printing: the fixture's `payload`/`version`
    // shape stored at this key is read verbatim by the (future) Datasets API.
    const parsed = JSON.parse(contents);
    return { key: `dataset:${name}`, value: JSON.stringify(parsed) };
  });

  const tmpDir = mkdtempSync(join(tmpdir(), "seatsignal-kv-bulk-"));
  const bulkFilePath = join(tmpDir, "bulk.json");
  writeFileSync(bulkFilePath, JSON.stringify(bulkEntries));

  try {
    const args = [
      "wrangler",
      "kv",
      "bulk",
      "put",
      bulkFilePath,
      "--binding=STATUS_CACHE",
      remote ? "--remote" : "--local",
    ];
    console.log(`Running: npx ${args.join(" ")}`);
    execFileSync("npx", args, {
      stdio: "inherit",
      cwd: join(import.meta.dirname, ".."),
    });
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }

  console.log(
    `Pushed ${bulkEntries.length} dataset key(s) to STATUS_CACHE (${remote ? "remote" : "local"}).`,
  );
}

main();
